from hypothesis import strategies as st

@st.composite
def gen(draw):
    n = draw(st.integers(1, 4))
    m = draw(st.integers(1, 8))
    a = draw(st.lists(st.integers(1, n), min_size=m, max_size=m))
    return f"{n} {m}\n{' '.join(map(str, a))}\n"

def validate(inp):
    lines = inp.split("\n")
    if len(lines) < 2:
        return False
    head = lines[0].split()
    if len(head) != 2:
        return False
    n, m = int(head[0]), int(head[1])
    if not (1 <= n <= 200000 and 1 <= m <= 200000):
        return False
    a_tokens = lines[1].split()
    if len(a_tokens) != m:
        return False
    a = [int(x) for x in a_tokens]
    return all(1 <= x <= n for x in a)

def ref(inp):
    lines = inp.split("\n")
    n, m = map(int, lines[0].split())
    a = [int(x) for x in lines[1].split()][:m]
    counts = [0] * (n + 1)
    out = []
    for i in range(m):
        counts[a[i]] += 1
        best_c = -1
        best_k = -1
        # candidates 1..n in increasing order; keep strictly greater counts only
        for k in range(1, n + 1):
            if counts[k] > best_c:
                best_c = counts[k]
                best_k = k
        out.append(str(best_k))
    return "\n".join(out) + "\n"
